"""Read-only usage aggregation over the node file protocol."""
import argparse
from datetime import datetime, timezone
import json
from pathlib import Path
import sys


class BadRecord(ValueError):
    pass


def read_object(path):
    try:
        with path.open("r", encoding="utf-8") as stream:
            value = json.load(stream)
    except (OSError, ValueError) as exc:
        raise BadRecord(str(exc)) from exc
    if not isinstance(value, dict):
        raise BadRecord("expected a JSON object")
    return value


def receipt_integer(value):
    if value is None:
        return 0
    if type(value) is not int:
        raise BadRecord("expected an integer or null")
    return value


def period_of(raw, by):
    if raw is None:
        return "-"
    at = raw.get("at")
    if type(at) not in (int, float):
        raise BadRecord("raw.at must be epoch seconds")
    try:
        stamp = datetime.fromtimestamp(at, timezone.utc)
    except (ValueError, OverflowError, OSError) as exc:
        raise BadRecord("invalid epoch seconds") from exc
    day = f"{stamp.year:04d}-{stamp.month:02d}-{stamp.day:02d}"
    return day if by == "day" else f"{day}T{stamp.hour:02d}"


def ledger_used(node, budget):
    try:
        value = read_object(node / "budget" / budget / "ledger.json").get("used")
    except BadRecord:
        return None
    return value if type(value) is int else None


def summarize(node, by):
    groups = {}
    budgets = {}
    gaps = []
    root = node / "llmcall"
    budget_dirs = sorted(root.iterdir()) if root.is_dir() else []
    for budget_dir in budget_dirs:
        if not budget_dir.is_dir():
            continue
        budget = budget_dir.name
        total = 0
        for call_dir in sorted(budget_dir.iterdir()):
            if not call_dir.is_dir() or not (call_dir / "request.json").is_file():
                continue
            call_id = call_dir.name
            reasons = set()
            records = {}
            for name in ("request", "receipt", "raw"):
                path = call_dir / (name + ".json")
                if name != "request" and not path.exists():
                    records[name] = None
                    if name == "receipt":
                        reasons.add("no_receipt")
                    continue
                try:
                    records[name] = read_object(path)
                except BadRecord:
                    records[name] = None
                    reasons.add("bad_json")
            if not reasons:
                try:
                    request = records["request"]
                    payload = request.get("request")
                    model = payload.get("model") if isinstance(payload, dict) else None
                    if not isinstance(model, str):
                        model = request.get("endpoint", "")
                    holder = request.get("holder", "")
                    if not isinstance(model, str) or not isinstance(holder, str):
                        raise BadRecord("model/endpoint and holder must be strings")
                    period = period_of(records["raw"], by)
                    used = receipt_integer(records["receipt"].get("used"))
                    overrun = receipt_integer(records["receipt"].get("overrun"))
                except BadRecord:
                    reasons.add("bad_json")
                else:
                    # Commit both accounting totals only after the entire call validates.
                    key = (model, holder, period)
                    group = groups.setdefault(key, {
                        "model": model, "holder": holder, "period": period,
                        "calls": 0, "used": 0, "overrun": 0,
                    })
                    group["calls"] += 1
                    group["used"] += used
                    group["overrun"] += overrun
                    total += used
                    if overrun > 0:
                        reasons.add("overrun")
            for why in reasons:
                gaps.append({"budget": budget, "call_id": call_id, "why": why})
        ledger = ledger_used(node, budget)
        budgets[budget] = {
            "receipts_used": total,
            "ledger_used": ledger,
            "diff": None if ledger is None else ledger - total,
        }
    return {
        "v": 1,
        "by": by,
        "groups": [groups[key] for key in sorted(groups)],
        "budgets": budgets,
        "gaps": sorted(gaps, key=lambda gap: (gap["budget"], gap["call_id"], gap["why"])),
    }


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("node", type=Path)
    parser.add_argument("--by", choices=("day", "hour"), default="day")
    args = parser.parse_args(argv)
    if not args.node.is_dir():
        parser.error("node must be a directory")
    try:
        result = summarize(args.node, args.by)
    except OSError as exc:
        print("aos7-usage: " + str(exc), file=sys.stderr)
        return 2
    print(json.dumps(result, ensure_ascii=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
